INSERT INTO `task_templates` VALUES (1,1,'Авторизация на сайте DO',16,'Авторизация на сайте','ГПОУ  Краснокаменский медицинский  колледж закомплектовал на курсы \"Обществознание. Современное состояние предмета в контексте изменений законодательства и введения единых государственных учебников\" преподавателя Ушакова Юлия Валентиновна. Не можем авторизоваться на сайте https://do75.zabedu.ru','in_progress','normal',12,'[]','[\"Проверка записи на zabedu.ru, пользователь зарегистрирован\", \"Сверка логина\", \"Авторизация на do75.zabedu.ru с данными пользователя\", \"Проверка зачисления на курс\"]','[]','[]','2026-06-16 00:44:29'),(2,1,'Авторизация на сайте DO',16,'Авторизация на сайте','ГПОУ  Краснокаменский медицинский  колледж закомплектовал на курсы \"Обществознание. Современное состояние предмета в контексте изменений законодательства и введения единых государственных учебников\" преподавателя Ушакова Юлия Валентиновна. Не можем авторизоваться на сайте https://do75.zabedu.ru','done','high',12,'[]','[\"Проверка записи на zabedu.ru, пользователь зарегистрирован\", \"Сверка логина\", \"Авторизация на do75.zabedu.ru с данными пользователя\", \"Проверка зачисления на курс\"]','[]','[]','2026-06-16 01:15:25'),(3,1,'Пароль от почты zimbra',16,'Пароль от сайта','Не могут авторизоваться на почте. Пояснил алгоритм дальнейших действий.','in_progress','normal',12,'[]','[\"Проверка аккаунта на рассылку спама\", \"Получение заявки на смену пароля\", \"Отправка ответа со ссылкой на инструкцию\"]','[]','[]','2026-07-20 02:08:14'),(4,1,'Пароль от почты zimbra',16,'Пароль от сайта','Не могут авторизоваться на почте. Пояснил алгоритм дальнейших действий.','in_progress','normal',12,'[]','[\"Проверка аккаунта на рассылку спама\", \"Инструктаж сотрудника ОО по дальнейшим действиям\", \"Получение заявки на смену пароля\", \"Отправка ответа со ссылкой на инструкцию\"]','[]','[]','2026-07-20 02:09:37'),(5,1,'Создание новой ОО',16,'Создание новой ОО','Поступила заявка на регистрацию нового лицея','in_progress','normal',12,'[]','[\"Поиск ОО на ОПЗК по ИНН и ОГРН\", \"Поиск по ключевым словам\", \"Проверка в интернете на соответствие информации\", \"Добавление новой ОО\", \"Регистрация ldap на корпоративной почте\", \"Отправка по обратному адресу логина, временного пароля и инструкции для дальнейших действий\"]','[]','[]','2026-07-20 02:37:44'),(6,1,'Техническое сопровождение \"защиты работ\"',16,'Техническое сопровождение мероприятия','Подготовить оборудование и провести сопровождение защиты выпускных квалификационных работ в аудитории 332','in_progress','normal',12,'[]','[\"Проверка оборудования (интернет, панель, камера, микрофоны)\", \"Загрузка работ выпускников\", \"Подключение к звонку, проверка соединения с представителями аттестационной коммисии\", \"Запись выступления\"]','[]','[]','2026-11-02 08:38:37'),(7,1,'Учёба на платформе \"Вектор\"',14,'Учёба на платформе \"Вектор\"','-','new','normal',136,'[]','[]','[]','[]','2026-11-05 03:43:34'),(8,1,'КПК для библиотекарей \"Современная школьная библиотека: направления модернизации\"',15,'КПК для библиотекарей \"Современная школьная библиотека: направления модернизации\"','Проверка практической работы 2.2','in_progress','normal',154,'[]','[]','[141]','[131]','2026-11-10 06:51:21');
