--
-- Table structure for table `tasks`
--

DROP TABLE IF EXISTS `tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tasks` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `organization_id` int unsigned NOT NULL,
  `work_year` smallint unsigned NOT NULL DEFAULT '2026' COMMENT 'Год плана организации',
  `project_id` int unsigned DEFAULT NULL,
  `title` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `status` enum('new','in_progress','review','done','cancelled') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'new',
  `my_plan_lane` enum('unplanned','active','week') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Мой план: не спланированы / в работе / на неделе',
  `priority` enum('low','normal','high','critical') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'normal',
  `author_id` int unsigned NOT NULL,
  `assignee_id` int unsigned DEFAULT NULL,
  `visible_department` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Видит вся кафедра проекта',
  `visible_institute` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Видит весь институт',
  `due_date` datetime DEFAULT NULL COMMENT 'Срок (дата и время)',
  `remind_at` date DEFAULT NULL COMMENT 'Напоминание по сроку (дата)',
  `recurrence` enum('none','weekly','monthly') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `transition_note` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Заметка при последнем смене статуса (год работы организации)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `status_changed_at` datetime DEFAULT NULL COMMENT 'Когда задача перешла в текущий status',
  `is_quick_task` tinyint(1) NOT NULL DEFAULT '0' COMMENT 'Быстрая задача',
  `quick_visible_managers` tinyint(1) NOT NULL DEFAULT '1' COMMENT '1 — видно руководителю отдела в отчётах',
  PRIMARY KEY (`id`),
  KEY `idx_tasks_org_status` (`organization_id`,`status`),
  KEY `idx_tasks_org_year` (`organization_id`,`work_year`),
  KEY `idx_tasks_org_created` (`organization_id`,`created_at`),
  KEY `idx_tasks_org_updated` (`organization_id`,`updated_at`,`id`),
  KEY `idx_tasks_org_assignee_status_due` (`organization_id`,`assignee_id`,`status`,`due_date`),
  KEY `idx_tasks_assignee` (`assignee_id`),
  KEY `idx_tasks_project` (`project_id`),
  KEY `idx_tasks_remind` (`organization_id`,`remind_at`),
  KEY `fk_tasks_author` (`author_id`),
  KEY `idx_tasks_org_author` (`organization_id`,`author_id`),
  KEY `idx_tasks_org_status_updated_id` (`organization_id`,`status`,`updated_at`,`id`),
  KEY `idx_tasks_org_quick_created` (`organization_id`,`is_quick_task`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=447 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

